PRAGMA foreign_keys=ON; CREATE TABLE t1(node PRIMARY KEY,parent REFERENCES t1 ON DELETE CASCADE); CREATE TABLE t2(node PRIMARY KEY,parent); CREATE TRIGGER t2t AFTER DELETE ON t2 BEGIN DELETE FROM t2 WHERE parent=old.node; END; INSERT INTO t1 VALUES(1,NULL),(2,1),(3,1),(4,2),(5,2),(6,3),(7,3); INSERT INTO t2 SELECT * FROM t1;